(()=>{
 'use strict';
 let user=null,ready=false,busy=false,message='',report=null,history=[],confirmed=false,version=0,needsReview=false;
 let preparingMissing=false;
 let generated={},generating=new Set(),generationErrors={};
 const pause=ms=>new Promise(r=>setTimeout(r,ms));
 async function api(url,method='GET',body){
  let r;try{r=await fetch('/api/'+url,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(110000)});}catch{throw Error('Не удалось дождаться сервера. Текст сохранён. Проверь соединение и повтори запрос.');}
  let d;try{d=await r.json();}catch{throw Error('Сервер вернул неожиданный ответ. Текст сохранён; повтори запрос позже.');}
  if(!r.ok){const error=Error(d.error||'Не удалось выполнить запрос.');error.status=r.status;throw error;}return d;
 }
 const safe=x=>esc(String(x??''));
 const validReport=r=>r&&typeof r.summary==='string'&&['errors','topics','limitations'].every(k=>Array.isArray(r[k]));
 const draftKey=()=>user?'ponyatno-ai-draft-v2:'+user.id:null;
 function persist(){if(!user)return;try{localStorage.setItem(draftKey(),JSON.stringify({text:state.scanText,report,generated,at:Date.now(),needsReview}));}catch{message='Браузер не смог сохранить черновик. Скопируй текст перед закрытием страницы.';}}
 function restore(){try{const d=JSON.parse(localStorage.getItem(draftKey())||'null');if(d&&Date.now()-d.at<7*86400000&&typeof d.text==='string'){state.scanText=d.text;report=validReport(d.report)?d.report:null;generated=d.generated&&typeof d.generated==='object'?d.generated:{};needsReview=!!d.needsReview;message='Восстановлен черновик. Сверь текст с работой перед проверкой.';}}catch{}}
 function practiceHTML(r){
  const source=[...r.topics,...r.errors.map(e=>({title:e.topic,reason:e.problem}))].filter((t,i,a)=>t.title&&a.findIndex(x=>x.title===t.title)===i);
  const {matches,unmatched}=window.SCHOOL_AI_TOPIC_MATCHER.match(source,C,state.grade);
  return `<section class="ai-study-section"><h3>Закрепи темы на карточках</h3><p>Открой объяснение или реши задания по темам из разбора. Похожие рекомендации объединены.</p><div class="ai-study-list">${matches.map(({topic:t,reasons})=>{const questions=C.questions(t.id);return `<article class="ai-study-topic" data-ai-matched-topic="${esc(t.id)}"><span>${safe(C.subjectById(t.subject)?.name||'')} · ${t.grade} класс · ${questions.length} карточек</span><h4>${safe(t.title)}</h4><p>Из разбора: ${reasons.map(safe).join('; ')}.</p><div class="ai-study-actions"><button class="btn btn-orange" data-ai-study="${esc(t.id)}" data-ai-index="0">Начать практику</button><button class="btn btn-light" data-ai-topic="${esc(t.id)}">Объяснение темы</button></div><ol class="ai-study-cards">${questions.map((q,i)=>`<li><button data-ai-study="${esc(t.id)}" data-ai-index="${i}"><small>Карточка ${i+1}${q.stage?' · '+safe(q.stage):''}</small>${safe(q.prompt)}</button></li>`).join('')}</ol></article>`;}).join('')}</div>${unmatched.map(title=>generatedHTML(title)).join('')}${!matches.length&&!unmatched.length?'<p>Тем для практики по этой работе пока не назначено.</p>':''}</section>`;
 }
 function generatedHTML(title){const data=generated[title];return `<article class="ai-study-topic"><span>Дополнительные карточки по теме</span><h4>${safe(title)}</h4>${data?.cards?.length?data.cards.map((c,i)=>`<section class="ai-generated-card"><small>Карточка ${i+1}</small><h4>${safe(c.question)}</h4><label>Твой ответ<textarea class="textarea" aria-label="Твой ответ на карточку ${i+1}"></textarea></label><details><summary>Показать ответ и объяснение</summary><p>${safe(c.answer)}</p><p>${safe(c.explanation)}</p></details></section>`).join('')+ '<p>Карточки подготовлены нейросетью. Сравни свой ответ с объяснением.</p>':`<p role="status">${generating.has(title)?'Готовим карточки по этой теме…':safe(generationErrors[title]||'В библиотеке нет точного набора. Подготовим задания специально по этой теме.')}</p><button class="btn btn-orange" data-ai-generate="${esc(title)}" ${generating.has(title)?'disabled':''}>${generationErrors[title]?'Повторить подготовку':'Подготовить карточки'}</button>`}</article>`;}
 async function prepareCards(title){if(!user||generating.has(title)||generated[title])return;generating.add(title);delete generationErrors[title];render();try{const item=report?.topics.find(t=>t.title===title);const error=report?.errors.find(e=>e.topic===title);generated[title]=await api('practice','POST',{title,reason:(item?.reason||error?.problem||'').slice(0,3000),grade:state.grade});persist();}catch(e){generationErrors[title]=e.message;}finally{generating.delete(title);render();}}
 async function prepareMissing(){if(preparingMissing||!report||!user)return;preparingMissing=true;try{while(report&&user){const source=[...report.topics,...report.errors.map(e=>({title:e.topic,reason:e.problem}))];const {unmatched}=window.SCHOOL_AI_TOPIC_MATCHER.match(source,C,state.grade);const next=unmatched.find(title=>!generated[title]&&!generationErrors[title]&&!generating.has(title));if(!next)break;await prepareCards(next);}}finally{preparingMissing=false;}}

 function reportHTML(r){return `<section class="card ai-report" id="ai-report"><h2>Результат разбора</h2><p>${safe(r.summary)}</p><h3>Ошибки в работе</h3>${r.errors.length?r.errors.map(e=>`<article class="diagnostic-error"><h3>${safe(e.topic)}</h3><p>В работе: ${safe(e.fragment)}</p><p>${safe(e.problem)}</p><p>Как исправить: ${safe(e.correction)}</p></article>`).join(''):'<p>В доступном тексте модель не указала конкретных ошибок. Учитывай ограничения проверки ниже.</p>'}<h3>Темы для повторения</h3>${r.topics.map(t=>`<article class="diagnostic-error"><h3>${safe(t.title)}</h3><p>${safe(t.reason)}</p><p>Попробуй: ${safe(t.practice)}</p></article>`).join('')||'<p>Недостаточно оснований для назначения тем.</p>'}${practiceHTML(r)}${r.limitations.length?'<h3>Что не удалось проверить</h3>'+r.limitations.map(t=>`<p>${safe(t)}</p>`).join(''):''}<p>Разбор выполнен нейросетью. Одна работа не доказывает устойчивый пробел в знаниях.</p></section>`;}
 scan=()=>`${head('РАЗБОР РАБОТЫ','Разберём работу по шагам','Прочитаем рукопись, объясним ошибки и выберем темы для повторения.')}<section class="card scan-panel ai-scan-panel"><p>${!ready?'Подключаем профиль…':user?'Профиль: '+safe(user.name):'Для проверки войди в профиль. Материалы доступны без входа.'}</p>${ready&&!user?'<a class="btn btn-blue" href="index.html#login">Войти</a>':''}<p>При чтении фото и разборе текст передаётся в Google Gemini. В профиле сохраняются текст и результат, без фотографий. Черновик текста сохраняется в этом браузере на семь дней.</p><label class="upload-zone" for="photoInput"><strong>Выбрать фотографии</strong><small>До четырёх страниц JPG, PNG или WEBP, до 8 МБ каждая</small><input id="photoInput" type="file" accept="image/jpeg,image/png,image/webp" multiple ${busy||!ready?'disabled':''}></label><div class="ai-upload-grid">${state.photos.map((p,i)=>`<div class="ai-upload-item"><img src="${esc(p.url)}" alt="Страница ${i+1}"><button class="btn btn-light" data-ai-remove="${i}" ${busy?'disabled':''}>Убрать</button></div>`).join('')}</div><button class="btn btn-blue" data-ai-ocr ${!user||busy||!state.photos.length?'disabled':''}>${state.photos.some(p=>p.ocrResult)?'Продолжить чтение фото':'Прочитать фото'}</button><p role="status" aria-live="polite" style="white-space:pre-wrap">${safe(message)}</p><label for="scanText">Проверь текст и исправь неточности. Нужны условия и решения.</label><textarea id="scanText" class="textarea" maxlength="40000" ${busy||!ready?'disabled':''}>${esc(state.scanText)}</textarea>${state.scanText.length>40000?'<p>Текст длиннее 40 000 символов. Раздели работу на части перед анализом.</p>':''}${needsReview?'<p>Работа прочитана не полностью. Исправь или дополни текст вручную либо продолжи чтение фотографий.</p>':''}<label class="ai-review-check"><input type="checkbox" id="aiConfirm" ${confirmed?'checked':''} ${busy||needsReview?'disabled':''}>Текст полный и совпадает с работой ученика</label><div class="task-actions"><button class="btn btn-orange" data-ai-analyze ${!user||busy||!confirmed||needsReview||state.scanText.length>40000||!state.scanText.trim()?'disabled':''}>Разобрать ошибки и выбрать темы</button><button class="btn btn-light" data-ai-clear ${busy?'disabled':''}>Очистить черновик</button></div><p>Во время проверки можно перейти в другой раздел. Текст и готовый разбор останутся в черновике после обновления страницы.</p></section>${report?reportHTML(report):''}`;
 const originalProfile=profile;
 profile=()=>originalProfile()+`<section class="card"><h2>Профиль на сервере</h2>${user?`<p>${safe(user.name)}</p><button class="btn btn-light" data-server-logout>Выйти</button><p>Прогресс и разборы доступны после входа на другом устройстве.</p>`:'<a class="btn btn-blue" href="index.html#login">Войти или зарегистрироваться</a>'}<h3>История разборов</h3>${history.map(w=>`<article><p>${new Date(w.created).toLocaleString('ru-RU')}</p><button class="btn btn-light" data-ai-open="${w.id}">Открыть разбор</button><button class="btn btn-light" data-ai-delete="${w.id}">Удалить</button></article>`).join('')||'<p>Сохранённых разборов пока нет.</p>'}</section>`;
 let timer,pending=Promise.resolve();const localSave=save;
 save=()=>{if(!ready)return;if(!user){localSave();return;}clearTimeout(timer);timer=setTimeout(()=>{const snapshot=JSON.parse(JSON.stringify({grade:state.grade,results:state.results}));pending=pending.catch(()=>{}).then(()=>api('progress','PUT',snapshot)).catch(e=>toast(e.message));},350);};
 document.addEventListener('input',e=>{if(e.target.id==='scanText'){confirmed=false;report=null;needsReview=false;version++;persist();const c=document.getElementById('aiConfirm');if(c){c.checked=false;c.disabled=false;}document.querySelector('[data-ai-analyze]')?.setAttribute('disabled','');}});
 // Own the upload event before the original local-only handler, which erased text.
 document.addEventListener('change',e=>{if(e.target.id!=='photoInput')return;e.stopImmediatePropagation();if(busy)return;let rejected=0,added=0;for(const f of [...e.target.files]){if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>8*1024*1024||state.photos.length>=4){rejected++;continue;}if(state.photos.some(p=>p.file.name===f.name&&p.file.size===f.size&&p.file.lastModified===f.lastModified))continue;state.photos.push({file:f,url:URL.createObjectURL(f)});added++;}if(added){confirmed=false;needsReview=true;report=null;version++;}message=(added?'Фото добавлено. Нажми «Прочитать фото». Текущий текст пока сохранён. ':'')+(rejected?'Часть файлов не добавлена: допустимы до четырёх JPG, PNG, WEBP, до 8 МБ каждый.':'');persist();render();},true);
 document.addEventListener('change',e=>{if(e.target.id==='aiConfirm'){confirmed=e.target.checked&&!needsReview;render();}});
 async function photoData(file){const bitmap=await createImageBitmap(file);try{if(Math.max(bitmap.width,bitmap.height)<=3000)return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Не удалось прочитать фото.'));reader.readAsDataURL(file);});const scale=3000/Math.max(bitmap.width,bitmap.height),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.94);}finally{bitmap.close();}}
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
  if(b.dataset.aiGenerate){void prepareCards(b.dataset.aiGenerate);return;}
  if(b.dataset.aiStudy&&!busy){const t=C.byId(b.dataset.aiStudy),i=Number(b.dataset.aiIndex);if(t&&C.questions(t.id)?.[i]){persist();startCard(t.id,i);}return;}
  if(b.dataset.aiTopic&&!busy){if(C.byId(b.dataset.aiTopic)){persist();openTopic(b.dataset.aiTopic);}return;}
  if(b.dataset.aiRemove!==undefined&&!busy){const p=state.photos[Number(b.dataset.aiRemove)];if(p){URL.revokeObjectURL(p.url);state.photos.splice(Number(b.dataset.aiRemove),1);confirmed=false;needsReview=state.photos.some(p=>!p.ocrResult);report=null;version++;persist();render();}return;}
  if(b.hasAttribute('data-ai-clear')&&!busy){state.scanText='';state.photos.forEach(p=>URL.revokeObjectURL(p.url));state.photos=[];report=null;confirmed=false;needsReview=false;version++;message='Черновик очищен.';persist();render();return;}
  if(b.hasAttribute('data-server-logout')){try{await pending;await api('auth/logout','POST',{});location.assign('index.html');}catch(e){toast(e.message);}return;}
  if(b.dataset.aiOpen&&!busy){const w=history.find(w=>w.id===b.dataset.aiOpen);if(w){report=w.report;state.scanText=w.text;confirmed=false;needsReview=false;persist();go('scan');prepareMissing();}return;}
  if(b.dataset.aiDelete){try{await api('works/'+b.dataset.aiDelete,'DELETE',{});history=history.filter(w=>w.id!==b.dataset.aiDelete);render();}catch(e){toast(e.message);}return;}
  const ocr=b.hasAttribute('data-ai-ocr'),analyze=b.hasAttribute('data-ai-analyze');if((!ocr&&!analyze)||busy||!user)return;
  if(analyze&&(!confirmed||needsReview||state.scanText.length>40000||!state.scanText.trim()))return;
  busy=true;const current=version;report=null;persist();let elapsed=0;const clock=setInterval(()=>{elapsed+=5;const status=document.querySelector('[role="status"]');if(status&&busy)status.textContent=message+` Прошло ${elapsed} сек.`;},5000);
  try{if(ocr){
   confirmed=false;let completed=0;const count=state.photos.length;
   for(const photo of state.photos){
    message=`Читаем страницу ${completed+1} из ${count}. При сбое сервер попробует резервную модель.`;render();
    let result=photo.ocrResult;
    if(!result){const image=await photoData(photo.file);result=await api('ocr','POST',{images:[image]});if(result.readable)photo.ocrResult=result;}
    if(version!==current)break;
    completed++;
    // Preserve all successful pages; a failed next request does not erase them.
    if(completed===1)state.scanText=result.text;else state.scanText+='\n\n'+result.text;
    needsReview=!result.readable||completed<count;persist();
    message=`Прочитано страниц: ${completed} из ${count}. `+(result.readable?'Сравни текст с фотографией.':'Исправь неразборчивые места в тексте или загрузи более чёткое фото.')+' '+result.uncertain.join(' ');render();
    if(!result.readable){needsReview=true;break;}
   }
  }else{
   const submitted=state.scanText;message='Проверяем решение. При сбое сервер попробует резервную модель.';render();
   const w=await api('analysis','POST',{text:submitted,confirmed:true,grade:state.grade});history=[w,...history.filter(x=>x.id!==w.id)];
   if(version===current){report=w.report;message='Разбор сохранён в профиле.';persist();prepareMissing();}
  }}catch(e){message=(ocr?'Не удалось закончить чтение фото. ':'Не удалось закончить анализ текста. ')+e.message;if(ocr)needsReview=true;persist();}finally{clearInterval(clock);busy=false;render();}
 });
 (async()=>{try{user=await api('me');const progress=await api('progress');state.grade=progress.grade;state.results=progress.results;restore();history=await api('works');}catch(e){if(e.status!==401)message=e.message;}finally{ready=true;render();prepareMissing();}})();
 render();
})();
